static const char HdCausticShaderFunctions[] = R"HLSL(float causticLayer(float2 p,float t,float flow,float3 tuning){ float a=0.34*sin(t*0.73+0.4),b=0.28*sin(t*1.13+1.9),c=0.22*sin(t*0.41+2.7); float2 q=p+float2(0.27*sin(p.y*2.1+a)+0.10*sin(p.x*2.3-p.y+b), 0.27*sin(p.x*1.9-b)+0.10*sin(p.y*2.1+p.x+c)); q=p+(q-p)*tuning.y; float2 cell=floor(q),f=frac(q);float first=8.0,second=8.0,third=8.0; [unroll]for(int y=-1;y<=1;++y){[unroll]for(int x=-1;x<=1;++x){  float2 g=float2(x,y),id=cell+g;  float2 seed=frac(sin(float2(dot(id,float2(127.1,311.7)),dot(id,float2(269.5,183.3))))*43758.5453);  float2 site=0.5+0.25*sin(seed*6.2831853)    +0.095*min(tuning.y,2.0)*sin(seed*6.2831853+float2(t*0.73+a,-t*1.13+b));  float2 r=g+site-f;float d=dot(r,r);  if(d<first){third=second;second=first;first=d;}else if(d<second){third=second;second=d;}else third=min(third,d);}} float gap=sqrt(second)-sqrt(first); float w1=0.5+0.5*sin(dot(p,float2(2.3,0.8))-t*5.2*flow+0.45*sin(p.y*1.6+t)); float w2=0.5+0.5*sin(dot(p,float2(-0.9,2.1))+t*3.7*flow+0.35*sin(p.x*1.8-t)); float envelope=0.22+0.92*smoothstep(0.12,0.90,w1*0.6+w2*0.4); envelope=max(0.05,1.0+(envelope-1.0)*tuning.z); float junction=1.0-smoothstep(0.025,0.24,sqrt(third)-sqrt(first)); float width=(0.044+0.042*envelope)*tuning.x*(1.0+2.2*junction);float aa=max(fwidth(gap)*0.5,0.006); float filteredWidth=sqrt(width*width+aa*aa); float ridge=exp2(-gap*gap/(filteredWidth*filteredWidth))*width/filteredWidth; return ridge*envelope*(1.0+0.15*junction);}float2 causticWaveWarp(float2 p,float t){ float2 a=p-float2(4.7,11.3),b=p-float2(31.2,-7.8),c=p-float2(-15.4,27.6); float da=length(a),db=length(b),dc=length(c); float2 radial=0.16*a/max(da,0.25)*sin(da*0.83-t*1.31) +0.13*b/max(db,0.25)*sin(db*1.07-t*1.09+2.1) +0.11*c/max(dc,0.25)*sin(dc*0.67-t*1.57+4.3); float2 crossing=float2(0.12*sin(dot(p,float2(0.61,0.79))-t*1.17), 0.10*sin(dot(p,float2(-0.86,0.51))+t*0.93+1.7)); return radial+crossing;}float waterCaustic(float2 p,float t,float4 causticGlobal,float4 causticA[5],float4 causticB[5]){ float values[5]; [unroll]for(int k=0;k<5;++k){ float4 a=causticA[k],b=causticB[k];float tk=t*a.y; float cs=cos(b.y),sn=sin(b.y);float2 pk=float2(p.x*cs-p.y*sn,p.x*sn+p.y*cs)*b.x; float2 warp=causticWaveWarp(pk,tk)*a.z;float2 q;float phase,flow; if(k==0){q=pk+float2(0.24,0.09)*tk*b.z+warp;phase=tk*3.35;flow=1.0;} else if(k==1){q=float2(pk.x*0.92-pk.y*0.39,pk.x*0.39+pk.y*0.92)*1.17+float2(7.3,13.1); q+=float2(-0.17,0.16)*tk*b.z+float2(-warp.y,warp.x)*0.85;phase=tk*2.73+4.2;flow=-1.0;} else if(k==2){q=float2(pk.x*0.799+pk.y*0.602,-pk.x*0.602+pk.y*0.799)*0.91+float2(23.7,-8.4); q+=float2(-0.13,-0.21)*tk*b.z-warp*0.72;phase=-tk*2.49+9.7;flow=1.0;} else if(k==3){q=float2(pk.x*0.292-pk.y*0.956,pk.x*0.956+pk.y*0.292)*1.08+float2(-17.2,31.6); q+=float2(0.19,-0.11)*tk*b.z+float2(warp.y,-warp.x)*1.12;phase=-tk*2.03+16.3;flow=-1.0;} else{q=pk+float2(41.6,-23.9)+float2(-0.11,0.18)*tk*b.z+float2(warp.y,-warp.x)*0.9;phase=tk*1.81+22.7;flow=1.0;} values[k]=a.x>0.0?causticLayer(q,phase,flow,float3(a.w,a.z,b.w)):0.0;} float combined=dot(float4(values[0],values[1],values[2],values[3]),float4(causticA[0].x,causticA[1].x,causticA[2].x,causticA[3].x))+values[4]*causticA[4].x; float junctionPulse=0.07*sqrt(max(0.0,values[0]*values[1]))*min(causticA[0].x/0.4,causticA[1].x/0.3); float signal=min(combined+junctionPulse,1.35); return causticGlobal.x*(1.12*signal+0.48*causticGlobal.y*(1.0-exp(-signal/0.12))*exp(-signal/0.55));})HLSL";
